/* Public discussion reads use RLS. Every mutation is validated by forum_action. */
(function(){
 'use strict';
 const $=id=>document.getElementById(id),safe=escapeHtml;
 const state={client:null,user:null,profile:null,people:new Map(),ready:false,error:'',thread:null,replies:[],page:0,topic:'all',unresolved:false,team:false,mode:'new_thread',edit:null,replyTo:null,generation:0};
 const expanded=new Set();
 let startup,io,refreshTimer,mathPromise;
 const threadDialog=document.createElement('dialog');threadDialog.id='forum-thread-dialog';threadDialog.className='forum-dialog';threadDialog.setAttribute('aria-label','题目讨论');
 threadDialog.innerHTML='<header><h2>题目讨论</h2><button type="button" data-forum-close aria-label="关闭讨论">×</button></header><p id="forum-thread-status" role="status" aria-live="polite"></p><div id="forum-thread-content"></div>';
 document.body.append(threadDialog);
 const editor=document.createElement('dialog');editor.id='forum-editor';editor.className='forum-dialog';editor.setAttribute('aria-labelledby','forum-editor-heading');
 editor.innerHTML=`<header><h2 id="forum-editor-heading">发起讨论</h2><button type="button" data-forum-close aria-label="关闭编辑">×</button></header><p id="forum-editor-status" role="status" aria-live="polite"></p><form id="forum-compose"><label id="forum-kind-label">类型<select name="kind"><option value="question">提问</option><option value="chat">交流</option></select></label><label>内容<textarea name="body" rows="8" maxlength="12000" placeholder="描述你的思路、卡住的步骤，或想交流的内容。" required></textarea></label><p class="forum-help">支持 **加粗**、列表、代码和 $公式$、$$独立公式$$。图片最多 3 张，每张不超过 5 MB，支持 PNG、JPEG、WebP。</p><div id="forum-existing-images"></div><label>添加图片<input name="files" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><div class="forum-actions"><button type="button" id="forum-preview">预览</button><button type="submit" id="forum-publish">发布</button></div><section id="forum-preview-content" hidden></section></form>`;
 document.body.append(editor);
 const nameDialog=document.createElement('dialog');nameDialog.className='forum-dialog';nameDialog.id='forum-name-dialog';nameDialog.innerHTML='<header><h2>论坛昵称</h2><button type="button" data-forum-close aria-label="关闭昵称设置">×</button></header><p>讨论中只展示昵称，不公开邮箱。</p><p id="forum-name-status" role="status"></p><form id="forum-name-form"><label>昵称<input name="nickname" minlength="2" maxlength="30" required autocomplete="nickname"></label><button>保存昵称</button></form>';document.body.append(nameDialog);
 document.addEventListener('click',e=>{const close=e.target.closest('[data-forum-close]');if(close)close.closest('dialog').close();});
 const date=x=>new Date(x).toLocaleString('zh-CN');
 function explain(e){const s=e?.message||'连接失败，请稍后重试。';return /PGRST|schema cache|does not exist|Could not find/i.test(s)?'讨论区正在开通，稍后刷新即可。':s;}
 async function init(){
  if(startup)return startup;
  startup=(async()=>{const {client,user}=await ChemyAccount.connection();state.client=client;state.user=user;await identity();const {error}=await client.from('forum_profiles').select('user_id').limit(1);if(error)throw error;state.ready=true;state.error='';return true;})().catch(e=>{state.ready=false;state.error=explain(e);startup=null;return false;});return startup;
 }
 async function identity(){
  const {client,user}=await ChemyAccount.connection();state.client=client;state.user=user;state.profile=null;
  if(user){const {data,error}=await client.from('forum_profiles').select('*').eq('user_id',user.id).maybeSingle();if(error)throw error;state.profile=data;if(data)state.people.set(user.id,data);}
  $('forum-admin-link').hidden=!state.profile?.is_admin;
 }
 async function people(ids){const missing=[...new Set(ids)].filter(id=>id&&!state.people.has(id));if(missing.length){const {data,error}=await state.client.from('forum_profiles').select('*').in('user_id',missing);if(error)throw error;data.forEach(p=>state.people.set(p.user_id,p));}}
 function person(id){const p=state.people.get(id);return `${safe(p?.display_name||'用户')} ${p?.is_team?'<span class="forum-badge">Chemy 团队成员</span>':''}${p?.is_admin?'<span class="forum-badge admin">管理员</span>':''}`;}
 function md(text){return String(text||'').split(/(```[\s\S]*?```)/g).map(part=>{if(part.startsWith('```'))return '<pre><code>'+safe(part.slice(3,-3))+'</code></pre>';return safe(part).replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>').split('\n').map(line=>/^[-*] /.test(line)?'<div class="forum-bullet">• '+line.slice(2)+'</div>':line.startsWith('&gt; ')?'<blockquote>'+line.slice(5)+'</blockquote>':line+'<br>').join('');}).join('');}
 function content(post){return '<div class="forum-body">'+(post.is_deleted?'这条发言已删除。':md(post.body))+'</div>'+(!post.is_deleted?(post.images||[]).map(path=>'<img class="forum-image" loading="lazy" alt="讨论附图" data-forum-image="'+safe(path)+'">').join(''):'');}
 async function decorate(root){
  if(!root?.isConnected)return;
  const imgs=[...root.querySelectorAll('[data-forum-image]')];if(imgs.length&&state.client){try{const paths=[...new Set(imgs.map(i=>i.dataset.forumImage))];const {data,error}=await state.client.storage.from('forum-images').createSignedUrls(paths,60);if(error)throw error;for(const item of data||[]){const url=item.signedUrl;if(url)imgs.filter(i=>i.dataset.forumImage===item.path).forEach(i=>i.src=url);}}catch{imgs.forEach(i=>i.alt='图片暂时无法加载，重新打开讨论可重试');}}
  if(![...root.querySelectorAll('.forum-body')].some(node=>/\$|\\\(|\\\[/.test(node.textContent)))return;
  try{if(!mathPromise){const link=document.createElement('link');link.rel='stylesheet';link.href='https://cdn.jsdelivr.net/npm/katex@0.19.1/dist/katex.min.css';document.head.append(link);mathPromise=import('https://cdn.jsdelivr.net/npm/katex@0.19.1/dist/contrib/auto-render.mjs');}const math=await mathPromise;if(root.isConnected)math.default(root,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false},{left:'\\(',right:'\\)',display:false},{left:'\\[',right:'\\]',display:true}],throwOnError:false,trust:false,maxExpand:1000});}catch{ /* Keep readable source formulas when the renderer is unavailable. */ }
 }
 function discussionSummary(body){const text=String(body||'').replace(/\s+/g,' ').trim().slice(0,140);return text.length>=2?text:text?text+'…':'图片讨论';}
 function card(t){return `<article class="forum-thread-card"><button type="button" class="forum-thread-main" data-open-thread="${safe(t.id)}"><span class="forum-kind">${t.kind==='question'?(t.accepted_reply?'已解决':'提问'):'交流'}</span><span>${safe(t.is_deleted?'原帖已删除':t.body.slice(0,180))}</span><small>${person(t.author_id)} · ${date(t.created_at)} · ${t.forum_replies?.[0]?.count||0} 条回复${t.is_locked?' · 已关闭':''}</small></button><div class="forum-actions"><button type="button" data-quick-reply="${safe(t.id)}" ${t.is_locked?'disabled':''}>回复</button><button type="button" data-open-thread="${safe(t.id)}">查看全部回复</button></div><p class="forum-card-status" role="status"></p></article>`;}
 async function quickReply(button){const note=button.closest('.forum-thread-card')?.querySelector('.forum-card-status');button.disabled=true;try{if(!await init())throw Error(state.error);const {data,error}=await state.client.from('forum_threads').select('*').eq('id',button.dataset.quickReply).single();if(error)throw error;if(data.is_locked)throw Error('此讨论已关闭，暂停新增回复。');state.thread=data;state.replyTo=null;state.quickReply=true;await compose('new_reply');}catch(e){if(note)note.textContent=explain(e);}finally{button.disabled=false;}}

 async function loadInline(node,all=false){
  if(node.dataset.forumBusy==='true')return;node.dataset.forumBusy='true';let version;
  const qid=node.dataset.discussion;
  try{
   node.innerHTML='<p class="forum-loading">正在读取本题讨论…</p>';
   if(!await init())throw Error(state.error);version=state.generation;
   const query=state.client.from('forum_threads').select('*,forum_replies!forum_replies_thread_id_fkey(count)',{count:'exact'}).eq('question_id',qid).order('last_activity',{ascending:false});const {data,error,count}=await query.limit(all?50:3);if(error)throw error;await people(data.map(t=>t.author_id));if(!node.isConnected||version!==state.generation)return;
   const label=node.closest('.discussion-toggle')?.querySelector('[data-discussion-label]');if(label)label.textContent=`讨论与提问（${count}）`;
   node.innerHTML=data.map(card).join('')+(data.length?'':'<p>还没有讨论。可以提出疑问，或分享你的解题思路。</p>')+'<div class="forum-actions"><button type="button" data-new-discussion="'+safe(qid)+'">发起提问 / 交流</button><button type="button" data-all-discussion="'+safe(qid)+'">查看全部讨论</button></div>';
  }catch(e){if(node.isConnected)node.innerHTML='<p>'+safe(explain(e))+'</p><button type="button" data-retry-discussion="'+safe(qid)+'">重试</button>';}
  finally{delete node.dataset.forumBusy;if(version!==undefined&&version!==state.generation&&node.isConnected&&node.closest('details')?.open)setTimeout(()=>loadInline(node),0);}
 }
 function mount(){if(!ready)return;document.querySelectorAll('[data-discussion]:not([data-forum-mounted])').forEach(node=>{node.dataset.forumMounted='true';const panel=node.closest('.discussion-toggle');if(panel){panel.open=expanded.has(node.dataset.discussion);if(panel.open)loadInline(node);}});}
 document.addEventListener('toggle',event=>{const panel=event.target;if(!panel.classList?.contains('discussion-toggle'))return;const node=panel.querySelector('[data-discussion]');if(panel.open){expanded.add(node.dataset.discussion);loadInline(node);}else expanded.delete(node.dataset.discussion);},true);
 async function call(action,payload){const {data,error}=await state.client.rpc('forum_action',{action,payload:{...payload,expected_user:state.user?.id}});if(error)throw error;return data;}
 async function mustPost(){if(!await init())throw Error(state.error);await identity();if(!state.user){$('account-launch').click();return false;}if(!state.profile){editName();return false;}return true;}
 async function editName(){if(!await init()){return;}if(!state.user){$('account-launch').click();return;}$('forum-name-status').textContent='';$('forum-name-form').elements.nickname.value=state.profile?.display_name||'';nameDialog.showModal();}
 $('forum-name-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await call('set_name',{name:e.target.elements.nickname.value});state.people.delete(state.user.id);await identity();nameDialog.close();}catch(e){$('forum-name-status').textContent=explain(e);}finally{b.disabled=false;}};
 let composeQuestion='',keptImages=[];
 async function compose(mode,item,questionId){
  try{if(!await mustPost())return;state.mode=mode;state.edit=item||null;composeQuestion=questionId||state.thread?.question_id;keptImages=[...(item?.images||[])];const form=$('forum-compose');form.reset();form.elements.kind.value=item?.kind||'question';form.elements.body.value=item?.body||'';const isThread=mode.endsWith('thread');$('forum-kind-label').hidden=!isThread||mode.startsWith('edit');$('forum-editor-heading').textContent=mode==='new_thread'?'发起提问 / 交流':mode==='new_reply'?(state.replyTo?'回复这位用户':'回复讨论'):'编辑发言';$('forum-editor-status').textContent='';$('forum-preview-content').hidden=true;paintKept();editor.showModal();}catch(e){$('forum-thread-status').textContent=explain(e);}
 }
 function paintKept(){$('forum-existing-images').innerHTML=keptImages.map((p,i)=>`<span>已有图片 ${i+1} <button type="button" data-remove-image="${i}">移除</button></span>`).join('');}
 editor.addEventListener('click',e=>{const b=e.target.closest('[data-remove-image]');if(b){keptImages.splice(Number(b.dataset.removeImage),1);paintKept();}});
 $('forum-preview').onclick=()=>{const root=$('forum-preview-content');root.hidden=false;root.innerHTML=content({body:$('forum-compose').elements.body.value,images:keptImages});decorate(root);};
 $('forum-compose').onsubmit=async e=>{e.preventDefault();const form=e.target,b=$('forum-publish');b.disabled=true;editor.querySelector('[data-forum-close]').disabled=true;const uploaded=[];try{
  const owner=state.user?.id,files=[...form.elements.files.files];if(files.length+keptImages.length>3)throw Error('每条发言最多 3 张图片。');
  for(const file of files){if(file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('图片需为 PNG、JPEG 或 WebP，且每张不超过 5 MB。');}
  for(const file of files){const ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[file.type],path=owner+'/'+crypto.randomUUID()+'.'+ext;const {error}=await state.client.storage.from('forum-images').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;uploaded.push(path);}
  if(owner!==state.user?.id)throw Error('登录账户已变化，请重新打开编辑窗口。');
  const payload={body:form.elements.body.value,images:[...keptImages,...uploaded],title:discussionSummary(form.elements.body.value),kind:form.elements.kind.value,question_id:composeQuestion};
  if(state.mode==='new_reply'){payload.thread_id=state.thread.id;payload.reply_to=state.replyTo;}
  if(state.mode.startsWith('edit'))payload.id=state.edit.id;
  const data=await call(state.mode,payload);editor.close();form.reset();if(state.mode==='new_thread')await openThread(data.id);else if(!state.quickReply)await openThread(state.thread.id);else{state.quickReply=false;document.querySelectorAll('[data-quick-reply]').forEach(button=>{if(button.dataset.quickReply===state.thread.id){const note=button.closest('.forum-thread-card')?.querySelector('.forum-card-status');if(note)note.textContent='回复已发布。';}});}refreshInline(composeQuestion);if(window.communityView==='forum')renderPage();
 }catch(e){$('forum-editor-status').textContent=explain(e);if(uploaded.length)await state.client.storage.from('forum-images').remove(uploaded);}finally{b.disabled=false;editor.querySelector('[data-forum-close]').disabled=false;}};
 editor.addEventListener('cancel',e=>{if($('forum-publish').disabled)e.preventDefault();});
 function ownControls(post,type){const admin=state.profile?.is_admin,own=post.author_id===state.user?.id;return '<div class="forum-actions">'+(own&&!post.is_deleted?`<button data-edit-${type}="${safe(post.id)}">编辑</button><button data-delete-${type}="${safe(post.id)}">删除</button>`:'')+(admin?`<button data-moderate="hide_${type}" data-id="${safe(post.id)}" data-enabled="${!post.is_hidden}">${post.is_hidden?'恢复显示':'隐藏'}</button>`:'')+'</div>';}
 async function openThread(id,replyLimit=50){
  state.quickReply=false;
  if(!threadDialog.open)threadDialog.showModal();$('forum-thread-status').textContent='正在读取讨论…';$('forum-thread-content').replaceChildren();
  if(!await init()){$('forum-thread-status').textContent=state.error;return;}
  try{await identity();const {data:t,error}=await state.client.from('forum_threads').select('*').eq('id',id).single();if(error)throw error;const {data:replies,error:re,count:replyCount}=await state.client.from('forum_replies').select('*',{count:'exact'}).eq('thread_id',id).order('created_at').range(0,replyLimit-1);if(re)throw re;
   state.thread=t;state.replies=replies;state.replyTo=null;await people([t.author_id,...replies.map(r=>r.author_id)]);const q=byId.get(t.question_id);const canAccept=t.kind==='question'&&!t.is_deleted&&(state.user?.id===t.author_id||state.profile?.is_admin);
   $('forum-thread-status').textContent=t.is_hidden?'此讨论已隐藏，仅管理员可见。':t.is_locked?'此讨论已关闭，暂停新增回复。':'';
   $('forum-thread-content').innerHTML=`<button type="button" data-view-question="${safe(t.question_id)}">回看原题：${safe(q?questionTitle(q):t.question_id)}</button><article class="forum-post"><span class="forum-kind">${t.kind==='question'?(t.accepted_reply?'已解决':'提问'):'交流'}</span><p class="forum-meta">${person(t.author_id)} · ${date(t.created_at)}${t.edited_at?' · 已编辑':''}</p>${content(t)}${ownControls(t,'thread')}${state.profile?.is_admin?`<button data-moderate="lock_thread" data-id="${safe(t.id)}" data-enabled="${!t.is_locked}">${t.is_locked?'重新开放讨论':'关闭讨论'}</button>`:''}${canAccept&&t.accepted_reply?'<button data-accept="">重新打开提问</button>':''}</article><h3>回复（${replyCount}）</h3><div id="forum-replies">${replies.map(r=>`<article class="forum-post${t.accepted_reply===r.id?' accepted':''}" id="reply-${safe(r.id)}"><p class="forum-meta">${person(r.author_id)} · ${date(r.created_at)}${r.edited_at?' · 已编辑':''}${r.reply_to?' · 回复 '+person(replies.find(p=>p.id===r.reply_to)?.author_id):''}</p>${t.accepted_reply===r.id?'<strong class="forum-kind">已采纳</strong>':''}${content(r)}<div class="forum-actions">${!t.is_locked&&!r.is_deleted?`<button data-reply-to="${safe(r.id)}">回复这位用户</button>`:''}${canAccept&&!r.is_deleted&&!r.is_hidden&&t.accepted_reply!==r.id?`<button data-accept="${safe(r.id)}">采纳回复</button>`:''}</div>${ownControls(r,'reply')}</article>`).join('')}</div>${replyCount>replies.length?'<button id="forum-more-replies">加载更多回复</button>':''}<button id="forum-reply-button" ${t.is_locked?'disabled':''}>${state.user?'回复讨论':'登录后回复'}</button>`;
   if($('forum-more-replies'))$('forum-more-replies').onclick=()=>openThread(id,replyLimit+50);
   $('forum-reply-button').onclick=()=>{state.replyTo=null;compose('new_reply');};decorate($('forum-thread-content'));
  }catch(e){$('forum-thread-status').textContent=explain(e);}
 }
 function refreshInline(qid){document.querySelectorAll('[data-discussion]').forEach(n=>{if(n.dataset.discussion===qid&&n.dataset.forumMounted)loadInline(n);});}
 threadDialog.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
  if(b.dataset.viewQuestion){threadDialog.close();navigateQuestion(b.dataset.viewQuestion);return;}
  if(b.hasAttribute('data-reply-to')){state.replyTo=b.dataset.replyTo;await compose('new_reply');return;}
  for(const type of ['thread','reply']){const item=type==='thread'?state.thread:state.replies.find(r=>r.id===(b.dataset['edit'+type[0].toUpperCase()+type.slice(1)]||b.dataset['delete'+type[0].toUpperCase()+type.slice(1)]));if(b.hasAttribute('data-edit-'+type)){await compose('edit_'+type,item);return;}if(b.hasAttribute('data-delete-'+type)){if(!confirm('删除这条发言？已有回复会保留。'))return;await call('delete_'+type,{id:item.id});await openThread(state.thread.id);refreshInline(state.thread.question_id);return;}}
  if(b.hasAttribute('data-accept')){await call('accept',{thread_id:state.thread.id,reply_id:b.dataset.accept||null});await openThread(state.thread.id);refreshInline(state.thread.question_id);}
  if(b.dataset.moderate){await call(b.dataset.moderate,{id:b.dataset.id,enabled:b.dataset.enabled==='true'});await openThread(state.thread.id);refreshInline(state.thread.question_id);}
 }catch(e){$('forum-thread-status').textContent=explain(e);}});
 async function allDiscussion(qid,offset=0){
  if(!await init())return;
  if(!threadDialog.open)threadDialog.showModal();$('forum-thread-status').textContent='';const {data,error,count}=await state.client.from('forum_threads').select('*,forum_replies!forum_replies_thread_id_fkey(count)',{count:'exact'}).eq('question_id',qid).order('last_activity',{ascending:false}).range(offset,offset+19);if(error){$('forum-thread-status').textContent=explain(error);return;}await people(data.map(t=>t.author_id));const q=byId.get(qid);$('forum-thread-content').innerHTML=`<h2>${safe(q?questionTitle(q):qid)} · 全部讨论</h2><button data-new-discussion="${safe(qid)}">发起提问 / 交流</button>${data.map(card).join('')}<div class="forum-actions"><button id="forum-all-prev" ${offset===0?'disabled':''}>上一页</button><span>${offset+1}–${Math.min(count,offset+20)} / ${count}</span><button id="forum-all-next" ${offset+20>=count?'disabled':''}>下一页</button></div>`;$('forum-all-prev').onclick=()=>allDiscussion(qid,offset-20);$('forum-all-next').onclick=()=>allDiscussion(qid,offset+20);
 }
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.quickReply){await quickReply(b);return;}if(b.hasAttribute('data-community-login')){$('account-launch').click();return;}if(b.dataset.openThread){if(b.dataset.notificationId){await call('read_notifications',{id:b.dataset.notificationId});await unread();}await openThread(b.dataset.openThread);return;}if(b.dataset.newDiscussion){state.replyTo=null;await compose('new_thread',null,b.dataset.newDiscussion);return;}if(b.dataset.allDiscussion)await allDiscussion(b.dataset.allDiscussion);if(b.dataset.retryDiscussion){startup=null;const n=[...document.querySelectorAll('[data-discussion]')].find(n=>n.dataset.discussion===b.dataset.retryDiscussion);if(n)await loadInline(n);}}catch(e){$('forum-thread-status').textContent=explain(e);}});
 async function notifications(host){
  if(!state.user){host.innerHTML='<h1>消息</h1><button data-community-login>登录查看消息</button>';return;}
  const {data,error}=await state.client.from('forum_notifications').select('*').order('created_at',{ascending:false}).limit(100);if(error)throw error;await people(data.map(n=>n.actor));host.innerHTML='<h1>消息</h1><button id="forum-read-all">全部标为已读</button>'+data.map(n=>`<div class="forum-notification${n.is_read?'':' unread'}"><button data-open-thread="${safe(n.thread_id)}" data-notification-id="${safe(n.id)}">${person(n.actor)} ${n.kind==='accepted'?'采纳了你的回复':n.kind==='direct_reply'?'回复了你':'回复了你的讨论'} · ${date(n.created_at)}</button>${n.is_read?'':`<button data-read-notification="${safe(n.id)}">标为已读</button>`}</div>`).join('');$('forum-read-all').onclick=async()=>{await call('read_notifications',{});await unread();await renderPage();};host.querySelectorAll('[data-read-notification]').forEach(b=>b.onclick=async()=>{await call('read_notifications',{id:b.dataset.readNotification});await unread();await renderPage();});
 }
 async function unread(){if(!state.client||!state.user){$('forum-unread').textContent='0';return;}const {count,error}=await state.client.from('forum_notifications').select('id',{count:'exact',head:true}).eq('is_read',false);if(!error)$('forum-unread').textContent=count||0;}
 async function adminPage(host){
  if(!state.profile?.is_admin){host.innerHTML='<h1>论坛管理</h1><p>此页面仅管理员可访问。</p>';return;}
  host.innerHTML='<h1>论坛管理</h1><p>认证仅显示“Chemy 团队成员”，不会赋予管理权限。</p><form id="forum-user-search"><label>查找昵称<input name="query" type="search" maxlength="30" placeholder="昵称关键词"></label><button>查找</button></form><div id="forum-admin-users"></div><h2>已隐藏内容</h2><div id="forum-hidden"></div><h2>管理记录</h2><div id="forum-admin-log"></div>';
  async function search(){const text=$('forum-user-search').elements.query.value.trim();let q=state.client.from('forum_profiles').select('*').order('created_at',{ascending:false}).limit(30);if(text)q=q.ilike('display_name','%'+text.replace(/[%_]/g,'')+'%');const {data,error}=await q;if(error)throw error;const {data:bans,error:be}=await state.client.from('forum_bans').select('user_id');if(be)throw be;const banned=new Set(bans.map(b=>b.user_id));$('forum-admin-users').innerHTML=data.map(p=>`<div class="forum-admin-user"><strong>${safe(p.display_name)}</strong><small>${safe(p.user_id)}</small>${p.is_admin?'<span>管理员</span>':`<button data-user-action="set_team" data-id="${safe(p.user_id)}" data-enabled="${!p.is_team}">${p.is_team?'撤销团队认证':'认证为团队成员'}</button><button data-user-action="set_ban" data-id="${safe(p.user_id)}" data-enabled="${!banned.has(p.user_id)}">${banned.has(p.user_id)?'解除禁言':'禁言'}</button>`}</div>`).join('');}
  $('forum-user-search').onsubmit=e=>{e.preventDefault();search().catch(e=>{$('forum-admin-users').textContent=explain(e);});};await search();host.querySelector('#forum-admin-users').onclick=async e=>{const b=e.target.closest('[data-user-action]');if(!b)return;try{await call(b.dataset.userAction,{id:b.dataset.id,enabled:b.dataset.enabled==='true'});state.people.delete(b.dataset.id);await search();}catch(e){$('forum-admin-users').textContent=explain(e);}};
  const hidden=await Promise.all(['forum_threads','forum_replies'].map(table=>state.client.from(table).select('*').eq('is_hidden',true).limit(30)));$('forum-hidden').innerHTML=hidden.flatMap((res,i)=>(res.data||[]).map(post=>`<div class="forum-admin-user"><span>${safe(post.is_deleted?"原帖已删除":post.body.slice(0,80))}</span><button data-open-thread="${safe(i?post.thread_id:post.id)}">查看</button><button data-restore-hidden="${i?'hide_reply':'hide_thread'}" data-id="${safe(post.id)}">恢复显示</button></div>`)).join('');$('forum-hidden').onclick=async e=>{const b=e.target.closest('[data-restore-hidden]');if(!b)return;try{await call(b.dataset.restoreHidden,{id:b.dataset.id,enabled:false});await renderPage();}catch(e){$('forum-hidden').textContent=explain(e);}};
  const {data,error}=await state.client.from('forum_admin_log').select('*').order('created_at',{ascending:false}).limit(20);if(!error)$('forum-admin-log').innerHTML=data.map(l=>'<p>'+safe(date(l.created_at)+' · '+l.action+' · '+l.target)+'</p>').join('');
 }
 async function renderPage(){
  const view=window.communityView,host=$('community-content'),version=++state.generation;
  if(view==='history'){ChemyAccount.renderHistory();return;}
  if(!view)return;host.innerHTML='<h1>'+({forum:'题目讨论',notifications:'消息',admin:'论坛管理'}[view]||'题目讨论')+'</h1><p>正在读取…</p>';
  if(!await init()){if(version===state.generation)host.innerHTML='<h1>题目讨论</h1><p>'+safe(state.error)+'</p><button id="forum-retry-page">重试</button>';$('forum-retry-page')?.addEventListener('click',()=>{startup=null;renderPage();});return;}
  try{await identity();if(version!==state.generation||view!==window.communityView)return;if(view==='notifications'){await notifications(host);return;}if(view==='admin'){await adminPage(host);return;}
   let query=state.client.from('forum_recent').select('*',{count:'exact'}).order('last_activity',{ascending:false}).order('question_id');if(state.topic!=='all')query=query.eq('topic',state.topic);if(state.unresolved)query=query.gt('unresolved_count',0);if(state.team)query=query.eq('team_participated',true);const {data,error,count}=await query.range(state.page*20,state.page*20+19);if(error)throw error;if(version!==state.generation)return;
   host.innerHTML=`<h1>题目讨论</h1><p>从最近的交流，回到值得再想一遍的题目。</p><div class="forum-filters"><label>专题<select id="forum-topic">${option('all','全部专题',state.topic)+topics.map(t=>option(t,t,state.topic)).join('')}</select></label><label><input id="forum-unresolved" type="checkbox" ${state.unresolved?'checked':''}>有未解决提问</label><label><input id="forum-team" type="checkbox" ${state.team?'checked':''}>有团队成员参与</label></div><p>${count} 道题目有讨论</p>${data.map(q=>`<article class="forum-question-card"><button data-all-discussion="${safe(q.question_id)}"><strong>${safe(q.topic)} · 第 ${q.topic_number} 题 · ${safe(q.title)}</strong><span>${safe(q.latest_excerpt||'')}</span><small>${q.thread_count} 条讨论 · ${q.unresolved_count} 个未解决提问 · ${date(q.last_activity)}</small></button><button data-view-question="${safe(q.question_id)}">阅读原题</button></article>`).join('')||'<p>当前范围还没有讨论，欢迎在题目下发起第一条。</p>'}<div class="forum-actions"><button id="forum-prev" ${state.page===0?'disabled':''}>上一页</button><span>第 ${state.page+1} 页</span><button id="forum-next" ${(state.page+1)*20>=count?'disabled':''}>下一页</button></div>`;
   for(const id of ['forum-topic','forum-unresolved','forum-team'])$(id).onchange=()=>{state.topic=$('forum-topic').value;state.unresolved=$('forum-unresolved').checked;state.team=$('forum-team').checked;state.page=0;renderPage();};$('forum-prev').onclick=()=>{state.page--;renderPage();};$('forum-next').onclick=()=>{state.page++;renderPage();};host.querySelectorAll('[data-view-question]').forEach(b=>b.onclick=()=>navigateQuestion(b.dataset.viewQuestion));
  }catch(e){if(version===state.generation)host.innerHTML='<h1>题目讨论</h1><p>'+safe(explain(e))+'</p>';}
 }
 document.addEventListener('chemy-auth-changed',()=>{state.generation++;$('forum-admin-link').hidden=true;state.user=null;state.profile=null;state.people.clear();state.thread=null;state.replies=[];threadDialog.close();editor.close();nameDialog.close();$('forum-unread').textContent='0';setTimeout(async()=>{try{if(await init()){await identity();await unread();document.querySelectorAll('[data-discussion]').forEach(n=>{io?.unobserve(n);delete n.dataset.forumMounted;});mount();}if(window.communityView)renderPage();}catch{}},0);});
 window.ChemyForum={mount,renderPage,editName};
 document.addEventListener('chemy-library-ready',()=>{mount();init().then(ok=>{if(ok)unread();});if(window.communityView)renderPage();});
 if(ready){mount();if(window.communityView)renderPage();}
 refreshTimer=setInterval(()=>{if(!document.hidden)unread().catch(()=>{});},60000);
})();
